// match reports whether an invoice passes the filter.
func (f InvoiceFilter) match(inv Invoice) bool {
	return (f.CustomerID == "" || inv.CustomerID == f.CustomerID) && (f.SubscriptionID == "" || inv.SubscriptionID == f.SubscriptionID) &&
		(f.Status == "" || inv.Status == f.Status)
}

// InvoiceKey is an invoice's place in the list order: its creation time and ID.
type InvoiceKey struct {
	CreatedAt time.Time
	ID        string
}

// less reports whether the key comes before inv in the list order.
func (k InvoiceKey) less(inv Invoice) bool {
	if !k.CreatedAt.Equal(inv.CreatedAt) {
		return k.CreatedAt.Before(inv.CreatedAt)
	}
	return k.ID < inv.ID
}

// invoiceLess is the list order of invoices: oldest first, ties by ID. An invoice's creation time and ID never change, so its
// place in the order never does.
func invoiceLess(a, b Invoice) bool {
	return InvoiceKey{CreatedAt: a.CreatedAt, ID: a.ID}.less(b)
}

// indexInvoice puts a new invoice into its organization's list at its place in the order. The caller holds the lock.
func (s *Store) indexInvoice(inv Invoice) {
	ids := s.invoiceIDs[inv.OrgID]
	i := sort.Search(len(ids), func(i int) bool { return invoiceLess(inv, s.invoices[ids[i]]) })
	ids = append(ids, "")
	copy(ids[i+1:], ids[i:])
	ids[i] = inv.ID
	s.invoiceIDs[inv.OrgID] = ids
}

// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
	out, _ := s.InvoicePage(orgID, f, nil, math.MaxInt)
	return out
}

// InvoicePage returns up to limit of an organization's invoices that match f, in the order of ListInvoices, starting after
// the invoice at after (nil: from the first one). more reports whether a matching invoice follows the page. Each call finds
// its place by the key, so invoices created between pages are listed where they belong.
func (s *Store) InvoicePage(orgID string, f InvoiceFilter, after *InvoiceKey, limit int) ([]Invoice, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	ids := s.invoiceIDs[orgID]
	start := 0
	if after != nil {
		start = sort.Search(len(ids), func(i int) bool { return after.less(s.invoices[ids[i]]) })
	}
	out := []Invoice{}
	for _, id := range ids[start:] {
		inv := s.invoices[id]
		if !f.match(inv) {
			continue
		}
		if len(out) >= limit {
			return out, true
		}
		out = append(out, copyInvoice(inv))
	}
	return out, false
}

