300	// InvoiceFilter narrows ListInvoices.
301	type InvoiceFilter struct {
302		CustomerID     string
303		SubscriptionID string
304		Status         InvoiceStatus
305	}
306	
307	// match reports whether an invoice passes the filter.
308	func (f InvoiceFilter) match(inv Invoice) bool {
309		return (f.CustomerID == "" || inv.CustomerID == f.CustomerID) && (f.SubscriptionID == "" || inv.SubscriptionID == f.SubscriptionID) &&
310			(f.Status == "" || inv.Status == f.Status)
311	}
312	
313	// InvoiceKey is an invoice's place in the list order: its creation time and ID.
314	type InvoiceKey struct {
315		CreatedAt time.Time
316		ID        string
317	}
318	
319	// less reports whether the key comes before inv in the list order.
320	func (k InvoiceKey) less(inv Invoice) bool {
321		if !k.CreatedAt.Equal(inv.CreatedAt) {
322			return k.CreatedAt.Before(inv.CreatedAt)
323		}
324		return k.ID < inv.ID
325	}
326	
327	// invoiceLess is the list order of invoices: oldest first, ties by ID. An invoice's creation time and ID never change, so its
328	// place in the order never does.
329	func invoiceLess(a, b Invoice) bool {
330		return InvoiceKey{CreatedAt: a.CreatedAt, ID: a.ID}.less(b)
331	}
