333	// indexInvoice puts a new invoice into its organization's list at its place in the order. The caller holds the lock.
334	func (s *Store) indexInvoice(inv Invoice) {
335		ids := s.invoiceIDs[inv.OrgID]
336		i := sort.Search(len(ids), func(i int) bool { return invoiceLess(inv, s.invoices[ids[i]]) })
337		ids = append(ids, "")
338		copy(ids[i+1:], ids[i:])
339		ids[i] = inv.ID
340		s.invoiceIDs[inv.OrgID] = ids
341	}
342	
343	// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
344	func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
345		out, _ := s.InvoicePage(orgID, f, nil, math.MaxInt)
346		return out
347	}
348	
349	// InvoicePage returns up to limit of an organization's invoices that match f, in the order of ListInvoices, starting after
350	// the invoice at after (nil: from the first one). more reports whether a matching invoice follows the page. Each call finds
351	// its place by the key, so invoices created between pages are listed where they belong.
352	func (s *Store) InvoicePage(orgID string, f InvoiceFilter, after *InvoiceKey, limit int) ([]Invoice, bool) {
353		s.mu.Lock()
354		defer s.mu.Unlock()
355		ids := s.invoiceIDs[orgID]
356		start := 0
357		if after != nil {
358			start = sort.Search(len(ids), func(i int) bool { return after.less(s.invoices[ids[i]]) })
359		}
360		out := []Invoice{}
361		for _, id := range ids[start:] {
362			inv := s.invoices[id]
363			if !f.match(inv) {
364				continue
365			}
366			if len(out) >= limit {
367				return out, true
368			}
369			out = append(out, copyInvoice(inv))
370		}
371		return out, false
372	}
