374	// UpdateInvoice changes an invoice with f, which may refuse with an error. Only its status, timestamps and lines change.
375	func (s *Store) UpdateInvoice(orgID, id string, f func(*Invoice) error) (Invoice, error) {
376		s.mu.Lock()
377		defer s.mu.Unlock()
378		old, ok := s.invoices[id]
379		if !ok || old.OrgID != orgID {
380			return Invoice{}, ErrNotFound
381		}
382		inv := copyInvoice(old)
383		if err := f(&inv); err != nil {
384			return Invoice{}, err
385		}
386		inv.ID, inv.OrgID, inv.CustomerID, inv.SubscriptionID, inv.Currency, inv.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.SubscriptionID, old.Currency, old.CreatedAt
387		s.invoices[id] = copyInvoice(inv)
388		return copyInvoice(inv), nil
389	}
