391	// copyInvoice is a deep copy, so callers cannot change stored lines.
392	func copyInvoice(inv Invoice) Invoice {
393		inv.Lines = append([]Line(nil), inv.Lines...)
394		for _, p := range []**time.Time{&inv.PeriodStart, &inv.PeriodEnd, &inv.PaidAt, &inv.VoidedAt} {
395			if *p != nil {
396				t := **p
397				*p = &t
398			}
399		}
400		return inv
401	}
